/// <reference types="vitest/config" />
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// Frontend calls the backend at POST /api/v1/evaluate. The dev server proxies
// any /api request to the FastAPI backend so the client can use a relative path.
export default defineConfig({
  plugins: [react()],
  server: {
    proxy: {
      '/api': {
        target: 'http://localhost:8000',
        changeOrigin: true,
      },
    },
  },
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: './src/tests/setup.ts',
    css: true,
  },
});

import js from '@eslint/js';
import tseslint from 'typescript-eslint';

export default tseslint.config(
  { ignores: ['dist', 'node_modules', 'coverage'] },
  {
    // Client (src) code: enforce strict typing, forbid `any`.
    files: ['src/**/*.{ts,tsx}'],
    extends: [js.configs.recommended, ...tseslint.configs.recommended],
    languageOptions: {
      ecmaVersion: 2020,
    },
    rules: {
      '@typescript-eslint/no-explicit-any': 'error',
    },
  }
);

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (rootElement) {
  createRoot(rootElement).render(
    <StrictMode>
      <App />
    </StrictMode>,
  );
}

// Root shell. The Calculator container (Task 12.4) will be mounted here.
export default function App(): JSX.Element {
  return (
    <main>
      <h1>Web Calculator</h1>
    </main>
  );
}

/*
 * Responsive, accessible styling is implemented in Task 13.
 * This file establishes the styles/ location per the design's module structure.
 */
:root {
  color-scheme: light dark;
}

// Vitest setup: registers jest-dom matchers (e.g. toBeInTheDocument) and
// cleans up the DOM between tests.
import '@testing-library/jest-dom/vitest';
import { afterEach } from 'vitest';
import { cleanup } from '@testing-library/react';

afterEach(() => {
  cleanup();
});

import { render, screen } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import App from '../App';

// Smoke test: confirms the test harness (vitest + jsdom + RTL + jest-dom) works.
describe('App', () => {
  it('renders the calculator heading', () => {
    render(<App />);
    expect(
      screen.getByRole('heading', { name: /web calculator/i }),
    ).toBeInTheDocument();
  });
});
